namespace SirketMotoru.CanliPano;

internal static class YazilimBorsasiHtml
{
    public const string Icerik = """
<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Yazılım Borsası v4.2</title>
<style>
:root{color-scheme:dark;--bg:#040711;--panel:#0b1525;--panel2:#101d31;--line:#233754;--text:#eef5ff;--muted:#8fa4c0;--green:#43e2a2;--blue:#63a9ff;--red:#ff6c7d;--yellow:#ffd166;--purple:#b58cff;--cyan:#42d6ee;--shadow:0 16px 48px #0008}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;padding:12px;background:radial-gradient(circle at 8% 0,#102a50 0,transparent 34%),radial-gradient(circle at 92% 0,#28194e 0,transparent 30%),var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}.shell{max-width:2100px;margin:auto}.top{position:sticky;top:7px;z-index:40;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 15px;border:1px solid var(--line);border-radius:16px;background:#091424ed;backdrop-filter:blur(15px);box-shadow:var(--shadow)}.brand{display:flex;align-items:center;gap:11px}.logo{width:44px;height:44px;border-radius:13px;display:grid;place-items:center;background:linear-gradient(135deg,var(--green),var(--blue),var(--purple));color:#03151c;font-weight:1000}.brand h1{font-size:19px;margin:0}.brand small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.status{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:7px}.pill{padding:7px 10px;border:1px solid var(--line);border-radius:999px;background:#0a1628;color:var(--muted);font-size:10px}.pill b{color:var(--text)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;background:var(--yellow)}.dot.ok{background:var(--green);box-shadow:0 0 12px var(--green)}.dot.bad{background:var(--red)}.tabs{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}.tab{cursor:pointer;padding:9px 13px;border:1px solid var(--line);border-radius:999px;background:#0a1628;color:var(--muted);font-weight:850}.tab.active{border-color:transparent;background:linear-gradient(135deg,var(--green),var(--blue));color:#03151c}.page[hidden]{display:none!important}.page:not([hidden]){display:grid;gap:12px}.card{overflow:hidden;border:1px solid var(--line);border-radius:15px;background:linear-gradient(180deg,#101c30ed,#08101ded);box-shadow:var(--shadow)}.head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}.title{font-size:13px;font-weight:950;letter-spacing:.05em}.note{margin-top:3px;color:var(--muted);font-size:9px}.kpis{display:grid;grid-template-columns:repeat(9,minmax(120px,1fr));gap:9px}.kpi{min-height:84px;padding:11px;border:1px solid var(--line);border-radius:13px;background:linear-gradient(180deg,#101d31,#091321);position:relative;overflow:hidden}.kpi:after{content:"";position:absolute;width:80px;height:80px;right:-34px;bottom:-44px;border-radius:50%;background:var(--a,var(--blue));filter:blur(30px);opacity:.25}.kpi span{display:block;color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:.08em}.kpi b{display:block;margin-top:10px;font-size:18px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.company-grid{display:grid;grid-template-columns:repeat(4,minmax(270px,1fr));gap:9px;padding:10px}.company{padding:12px;border:1px solid var(--line);border-radius:13px;background:#081321;position:relative;overflow:hidden}.company:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--c,var(--blue))}.company-top{display:flex;justify-content:space-between;gap:8px}.company-name{font-size:16px;font-weight:950}.company-id{font-size:8px;color:var(--muted);margin-top:3px}.rank{font-size:21px;font-weight:1000;color:var(--yellow)}.state{display:inline-block;margin-top:5px;padding:3px 6px;border:1px solid #28634f;border-radius:999px;color:var(--green);font-size:8px}.state.off{border-color:#743746;color:var(--red)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:9px}.metric{min-width:0;padding:7px;border:1px solid #1d2d45;border-radius:8px;background:#0d192b}.metric span{display:block;color:var(--muted);font-size:7px;text-transform:uppercase}.metric b{display:block;margin-top:3px;font-size:11px;overflow:hidden;text-overflow:ellipsis}.bars{display:grid;gap:5px;margin-top:8px}.barrow{display:grid;grid-template-columns:64px 1fr 31px;align-items:center;gap:5px;color:var(--muted);font-size:8px}.bar{height:5px;border-radius:99px;background:#17253b;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--blue),var(--green))}.chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}.chip{padding:3px 5px;border:1px solid #293c57;border-radius:6px;color:#c3d1e5;font-size:7px}.chip.good{border-color:#28634f;color:var(--green)}.tablewrap{overflow:auto;max-height:700px}table{width:100%;border-collapse:collapse;min-width:1000px;font-size:10px}th{position:sticky;top:0;z-index:2;padding:9px;border-bottom:1px solid var(--line);background:#101c30;color:var(--muted);text-align:left;font-size:8px;text-transform:uppercase;letter-spacing:.07em}td{padding:9px;border-bottom:1px solid #1b2a41;vertical-align:top}tr:hover td{background:#63a9ff09}.num{text-align:right;font-variant-numeric:tabular-nums}.name{font-weight:900}.small{margin-top:3px;color:var(--muted);font-size:8px}.good{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--yellow)}.muted{color:var(--muted)}.progress{min-width:90px;height:6px;border-radius:99px;background:#152239;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--purple),var(--cyan))}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.log{height:520px;overflow:auto;padding:9px 11px;background:#050a12;font:9px/1.45 Consolas,monospace}.logline{display:grid;grid-template-columns:65px 72px 1fr;gap:7px;padding:4px 0;border-bottom:1px dashed #18253a}.empty{padding:22px;text-align:center;color:var(--muted)}.home-separator{height:1px;background:linear-gradient(90deg,transparent,var(--line),transparent);margin:1px 0}.footer{text-align:center;padding:14px;color:var(--muted);font-size:8px}@media(max-width:1650px){.kpis{grid-template-columns:repeat(5,1fr)}.company-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:1200px){.company-grid{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}}@media(max-width:760px){body{padding:6px}.top{position:static;align-items:flex-start;flex-direction:column}.status{justify-content:flex-start}.kpis{grid-template-columns:repeat(2,1fr)}.company-grid{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="shell">
<header class="top"><div class="brand"><div class="logo">YB</div><div><h1>Yazılım Borsası v4.2</h1><small>Ana Sayfa bütün piyasa · Diğer sekmeler yalnız kendi paneli</small></div></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="connection">BAĞLANIYOR</b></span><span class="pill">Motor <b id="motor">—</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Gecikme <b id="latency">—</b></span><span class="pill" id="clock">—</span></div></header>
<nav class="tabs" aria-label="Borsa panelleri"><button class="tab active" data-view="home">Ana Sayfa</button><button class="tab" data-view="overview">Genel Borsa</button><button class="tab" data-view="apps">Uygulamalar</button><button class="tab" data-view="protocols">Protokoller</button><button class="tab" data-view="services">Hizmetler</button><button class="tab" data-view="finance">Finans & Banka</button><button class="tab" data-view="operations">Sözleşmeler & Yatırımlar</button><button class="tab" data-view="security">Güvenlik & Akış</button></nav>
<main id="home" class="page"></main>
<main id="overview" class="page" hidden></main>
<main id="apps" class="page" hidden></main>
<main id="protocols" class="page" hidden></main>
<main id="services" class="page" hidden></main>
<main id="finance" class="page" hidden></main>
<main id="operations" class="page" hidden></main>
<main id="security" class="page" hidden></main>
<div class="footer">8080 salt okunur piyasa ekranıdır · Ticari işlemler 8090 üzerinden yapılır</div>
</div>
<script>
const S={data:null,loading:false,activeView:'home',colors:['#43e2a2','#63a9ff','#b58cff','#ffd166','#42d6ee','#ff6c7d']};
const money=new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2});
const number=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2});
const integer=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0});
const m=v=>money.format(Number(v||0)),n=v=>number.format(Number(v||0)),i=v=>integer.format(Number(v||0));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const metric=(label,value,cls='')=>`<div class="metric"><span>${esc(label)}</span><b class="${cls}">${esc(value)}</b></div>`;
const chip=(value,cls='')=>`<span class="chip ${cls}">${esc(value)}</span>`;
function bar(label,value){const x=Math.max(0,Math.min(100,Number(value||0)));return `<div class="barrow"><span>${esc(label)}</span><div class="bar"><i style="width:${x}%"></i></div><b>${n(x)}</b></div>`}
function companyValue(c){const o=c.isletim||{},k=c.kodTabanliYayinlar||{},products=o.urunler||[],services=k.hizmetler||c.hizmetler||[],protocols=k.protokoller||[],contracts=o.sozlesmeler||[],invest=Object.values(o.yatirimSeviyeleri||{}).reduce((a,b)=>a+Number(b||0),0),users=products.reduce((a,p)=>a+Number(p.aktifKullaniciSayisi||0),0),capacity=products.reduce((a,p)=>a+Number(p.kullaniciKapasitesi||0),0)+services.reduce((a,h)=>a+Number(h.azamiEszamanliIs||0),0)*50,profit=products.reduce((a,p)=>a+Math.max(0,Number(p.toplamGelir||0)-Number(p.toplamGider||0)),0),history=Number(c.tamamlananIsSayisi||0)*30+Math.max(0,Number(c.netGelir||0))*0.08,quality=(Number(c.kodKalitesiPuani||0)+Number(c.performansPuani||0)+Number(c.guvenlikPuani||0)+Number(c.itibarPuani||0)+Number(c.guvenilirlikPuani||0)+Number(c.ortalamaMusteriMemnuniyeti||0))*180,ecosystem=Number(o.ekosistemPuani||0)*300+protocols.filter(p=>p.piyasada).length*9000+services.filter(h=>h.aktif).length*1200,contractsValue=contracts.reduce((a,x)=>a+(x.aktif?Number(x.tickOdemesi||0)*Math.max(1,Number(x.bitisTicki||0)-Number(S.data?.motor?.tickNumarasi||0)):Number(x.basariliTickSayisi||0)*80)-Number(x.ihlalSayisi||0)*500,0),cash=Math.max(0,Number(c.kasa||0))*0.15,debt=Number(o.toplamBorc||0)*1.15+Number(o.odenemeyenGider||0)*1.5+Number(o.temerrutSayisi||0)*5000;return Math.max(0,cash+users*55+capacity*4+profit*7+history+quality+ecosystem+contractsValue+invest*3500-debt)}
function companies(data){return (data.sirketler||[]).map(c=>({...c,hesaplananDeger:companyValue(c)})).sort((a,b)=>b.hesaplananDeger-a.hesaplananDeger)}
function kpiSection(data,list){const g=data.genel||{},apps=data.uygulamaPiyasasi||[],protocols=data.protokolPiyasasi||[],totalValue=list.reduce((a,c)=>a+c.hesaplananDeger,0),subs=list.reduce((a,c)=>a+Number(c.isletim?.toplamAboneSayisi||0),0);return `<section class="kpis">${[['Toplam şirket değeri',m(totalValue),'var(--purple)'],['Toplam kasa',m(g.toplamSirketKasasi),'var(--green)'],['Toplam borç',m(g.toplamBorc),'var(--red)'],['Aktif abone',i(subs),'var(--cyan)'],['Müşteri',i(g.toplamMusteriSayisi),'var(--blue)'],['Uygulama',`${i(apps.filter(x=>x.piyasada).length)} / ${i(apps.length)}`,'var(--blue)'],['Protokol',`${i(protocols.filter(x=>x.piyasada).length)} / ${i(protocols.length)}`,'var(--yellow)'],['Bağlı şirket',`${i(g.bagliSirketSayisi)} / ${i(g.toplamSirketSayisi)}`,'var(--green)'],['Siber olay',`${i(g.toplamEngellenenSaldiri)} / ${i(g.toplamBasariliSaldiri)}`,'var(--red)']].map(x=>`<div class="kpi" style="--a:${x[2]}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section>`}
function companySection(data,list){return `${kpiSection(data,list)}<section class="card"><div class="head"><div><div class="title">GENEL BORSA VE ŞİRKET DEĞER LİSTESİ</div><div class="note">Değer; geçmiş, ürün, kullanıcı, kapasite, hizmet, protokol, SLA, kalite, yatırım ve borç riskinden hesaplanır. Kasa yalnız %15 likidite katkısı taşır.</div></div></div><div class="company-grid">${list.map((c,index)=>{const o=c.isletim||{},apps=c.kodTabanliYayinlar?.uygulamalar||[],protocols=c.kodTabanliYayinlar?.protokoller||[];return `<article class="company" style="--c:${S.colors[index%S.colors.length]}"><div class="company-top"><div><div class="company-name">${esc(c.sirketAdi)}</div><div class="company-id">${esc(c.sirketKimligi)} · ${esc(c.sunucuAdresi)}:${esc(c.sunucuPortu)} · v${esc(c.sunucuSurumu||'—')}</div><span class="state ${c.bagli?'':'off'}">${c.bagli?'BAĞLI':'ÇEVRİMDIŞI'}</span></div><div class="rank">#${index+1}</div></div><div class="metrics">${metric('Şirket değeri',m(c.hesaplananDeger),'good')}${metric('Hisse',m(c.hesaplananDeger/10000))}${metric('Kasa',m(c.kasa))}${metric('Borç',m(o.toplamBorc),Number(o.toplamBorc)>0?'warn':'')}${metric('Abone',i(o.toplamAboneSayisi))}${metric('Hizmet',i((c.kodTabanliYayinlar?.hizmetler||c.hizmetler||[]).length))}${metric('Uygulama',`${apps.filter(x=>x.piyasada).length}/${apps.length}`)}${metric('Protokol',`${protocols.filter(x=>x.piyasada).length}/${protocols.length}`)}${metric('Gecikme',`${n(c.sonGecikmeMs)} ms`)}</div><div class="bars">${bar('Kod',c.kodKalitesiPuani)}${bar('Performans',c.performansPuani)}${bar('Güvenlik',c.guvenlikPuani)}${bar('İtibar',c.itibarPuani)}${bar('Güvenilir',c.guvenilirlikPuani)}${bar('Memnuniyet',c.ortalamaMusteriMemnuniyeti)}</div><div class="chips">${apps.map(x=>chip(`${x.uygulama?.uygulamaAdi||x.uygulama?.uygulamaKimligi} ${x.piyasada?'●':'○'}`,x.piyasada?'good':'')).join('')}${protocols.map(x=>chip(`${x.protokol?.protokolAdi||x.protokol?.protokolKimligi} ${x.piyasada?'●':'○'}`,x.piyasada?'good':'')).join('')}</div></article>`}).join('')||'<div class="empty">Şirket kaydı yok.</div>'}</div></section>`}
function appSection(data){const list=data.uygulamaPiyasasi||[];return `<section class="card"><div class="head"><div><div class="title">UYGULAMA VE ABONELİK PAZARI</div><div class="note">Teknik manifest, ticari yayın, fiyat, kullanıcı, kapasite, kalite ve gelir</div></div></div><div class="tablewrap"><table><thead><tr><th>Uygulama</th><th>Şirket</th><th>Kategori</th><th>Teknik</th><th>Ticari</th><th>Model</th><th class="num">Abonelik</th><th>Kullanıcı / Kapasite</th><th class="num">Kalite</th><th class="num">Memnuniyet</th><th class="num">Gelir</th></tr></thead><tbody>${list.map(x=>{const a=x.uygulama||{},d=x.dogrulama||{},u=x.urun||{},users=Number(u.aktifKullaniciSayisi||0),cap=Number(u.kullaniciKapasitesi||0),ratio=cap?Math.min(100,users/cap*100):0;return `<tr><td><div class="name">${esc(a.uygulamaAdi||a.uygulamaKimligi)}</div><div class="small">${esc(a.uygulamaKimligi)} · v${esc(a.surum||'—')} · ${(a.ozellikler||[]).length} özellik</div></td><td>${esc(x.sirketAdi)}</td><td>${esc(a.kategori||'—')}</td><td class="${d.gecerli?'good':'bad'}">${d.gecerli?'STANDARDI GEÇTİ':'EKSİK'}</td><td class="${x.piyasada?'good':'muted'}">${x.piyasada?(u.aktif?'YAYINDA':'DURDURULDU'):'8090 BEKLİYOR'}</td><td>${esc(u.fiyatlandirmaModeli||'—')}</td><td class="num">${x.piyasada?m(u.abonelikUcreti):'—'}</td><td><div>${i(users)} / ${i(cap)}</div><div class="progress"><i style="width:${ratio}%"></i></div></td><td class="num">${x.piyasada?n(u.urunKalitesi):'—'}</td><td class="num">${x.piyasada?n(u.urunMemnuniyeti):'—'}</td><td class="num good">${x.piyasada?m(u.toplamGelir):'—'}</td></tr>`}).join('')||'<tr><td colspan="11" class="empty">Kodlanmış uygulama yok.</td></tr>'}</tbody></table></div></section>`}
function protocolSection(data){const list=data.protokolPiyasasi||[];return `<section class="card"><div class="head"><div><div class="title">ÖZEL PROTOKOL PİYASASI</div><div class="note">Kodlanmış yetkinlik, şema, uyumluluk ve lisans durumu</div></div></div><div class="tablewrap"><table><thead><tr><th>Protokol</th><th>Sahip</th><th>Sürüm</th><th>Şema</th><th>Teknik</th><th>Ticari</th><th>Yetkinlikler</th><th>Uyumluluk</th></tr></thead><tbody>${list.map(x=>{const p=x.teknikProtokol||{};return `<tr><td><div class="name">${esc(p.protokolAdi||p.protokolKimligi)}</div><div class="small">${esc(p.protokolKimligi)}</div></td><td>${esc(x.sirketAdi)}</td><td>${esc(p.surum||'—')}</td><td>${esc(p.semaKimligi||'—')}</td><td class="${x.gecerli?'good':'bad'}">${x.gecerli?'GEÇERLİ':'EKSİK'}</td><td class="${x.piyasada?'good':'muted'}">${x.piyasada?'LİSANSLANABİLİR':'8090 BEKLİYOR'}</td><td>${(p.yetkinlikler||[]).map(y=>chip(`${y.yetkinlikKimligi} → ${y.hizmetKimligi}`)).join('')}</td><td>${(p.uyumluProtokoller||[]).map(y=>chip(y)).join('')||'—'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Özel protokol yok.</td></tr>'}</tbody></table></div></section>`}
function serviceSection(data){const list=data.hizmetPiyasasi||[];return `<section class="card"><div class="head"><div><div class="title">HİZMET PİYASASI</div><div class="note">Talep, şüpheli işler, bütçe, fiyat aralığı ve sağlayıcılar</div></div></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th class="num">Talep</th><th class="num">Şüpheli</th><th class="num">Zorluk</th><th class="num">Bütçe</th><th class="num">En ucuz</th><th class="num">En pahalı</th><th>Sağlayıcılar</th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="name">${esc(s.hizmetKimligi)}</div><div class="small">v${esc(s.hizmetSurumu)}</div></td><td class="num">${i(s.talepSayisi)}</td><td class="num ${Number(s.kotuNiyetliTalepSayisi)>0?'bad':''}">${i(s.kotuNiyetliTalepSayisi)}</td><td class="num">${n(s.ortalamaZorlukSeviyesi)}</td><td class="num">${m(s.toplamTalepButcesi)}</td><td class="num good">${s.enUcuzFiyat==null?'—':m(s.enUcuzFiyat)}</td><td class="num">${s.enPahaliFiyat==null?'—':m(s.enPahaliFiyat)}</td><td>${(s.saglayicilar||[]).map(x=>chip(`${x.sirketAdi} ${m(x.birimFiyat)} · K${n(x.kodKalitesiPuani)} P${n(x.performansPuani)} G${n(x.guvenlikPuani)}`,x.bagli?'good':'bad')).join('')||'<span class="bad">Sağlayıcı yok</span>'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Hizmet piyasası boş.</td></tr>'}</tbody></table></div></section>`}
function financeSection(data,list){const credits=(data.krediPiyasasi||[]).filter(x=>x.kredi);return `<section class="card"><div class="head"><div><div class="title">FİNANS VE ŞİRKET DEĞERLEMESİ</div><div class="note">Kasa dışı ekonomik varlıklar değerlemenin ana bölümüdür</div></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th class="num">Değer</th><th class="num">Hisse</th><th class="num">Kasa</th><th class="num">Borç</th><th class="num">Kredi notu</th><th class="num">Abone</th><th class="num">Ürün geliri</th><th class="num">Gider</th></tr></thead><tbody>${list.map(c=>{const o=c.isletim||{};return `<tr><td class="name">${esc(c.sirketAdi)}</td><td class="num good">${m(c.hesaplananDeger)}</td><td class="num">${m(c.hesaplananDeger/10000)}</td><td class="num">${m(c.kasa)}</td><td class="num ${Number(o.toplamBorc)>0?'warn':''}">${m(o.toplamBorc)}</td><td class="num">${i(o.krediNotu)}</td><td class="num">${i(o.toplamAboneSayisi)}</td><td class="num good">${m(o.toplamUrunGeliri)}</td><td class="num bad">${m(Number(o.toplamIsletmeGideri||0)+Number(o.toplamFinansmanGideri||0))}</td></tr>`}).join('')}</tbody></table></div></section><section class="card"><div class="head"><div class="title">AKTİF KREDİLER</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Tür</th><th class="num">Ana para</th><th class="num">Kalan</th><th class="num">Taksit</th><th class="num">Kalan taksit</th><th class="num">Gecikme</th><th>Durum</th></tr></thead><tbody>${credits.map(x=>{const k=x.kredi;return `<tr><td>${esc(x.sirketAdi)}</td><td>${esc(k.krediTuru)}</td><td class="num">${m(k.anaPara)}</td><td class="num warn">${m(k.kalanBorc)}</td><td class="num">${m(k.taksitTutari)}</td><td class="num">${i(k.kalanTaksit)}</td><td class="num ${Number(k.gecikmeSayisi)>0?'bad':''}">${i(k.gecikmeSayisi)}</td><td class="${k.aktif?'warn':'good'}">${k.aktif?'AKTİF':'KAPANDI'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Kredi kaydı yok.</td></tr>'}</tbody></table></div></section>`}
function operationSection(data){const contracts=data.sozlesmePiyasasi||[],invest=data.yatirimPiyasasi||[];return `<section class="card"><div class="head"><div class="title">SLA SÖZLEŞMELERİ</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Sözleşme</th><th>Kategori</th><th>Dönem</th><th class="num">Ödeme</th><th class="num">Başarı</th><th class="num">İhlal</th><th>Durum</th></tr></thead><tbody>${contracts.map(x=>{const s=x.sozlesme||{};return `<tr><td>${esc(x.sirketAdi)}</td><td class="name">${esc(s.baslik)}</td><td>${esc(s.kategori)}</td><td>${i(s.baslangicTicki)}–${i(s.bitisTicki)}</td><td class="num good">${m(s.tickOdemesi)}</td><td class="num">${i(s.basariliTickSayisi)}</td><td class="num ${Number(s.ihlalSayisi)>0?'bad':''}">${i(s.ihlalSayisi)}</td><td class="${s.aktif?'good':'muted'}">${s.aktif?'AKTİF':'BİTTİ'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Sözleşme yok.</td></tr>'}</tbody></table></div></section><section class="card"><div class="head"><div class="title">YATIRIM SEVİYELERİ</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Yatırım</th><th class="num">Seviye</th></tr></thead><tbody>${invest.map(x=>`<tr><td>${esc(x.sirketAdi)}</td><td class="name">${esc(x.yatirimTuru)}</td><td class="num good">${i(x.seviye)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Yatırım kaydı yok.</td></tr>'}</tbody></table></div></section>`}
function securitySection(data,list){const events=(data.olaylar||[]).slice().reverse();return `<section class="card"><div class="head"><div><div class="title">GÜVENLİK SIRALAMASI</div><div class="note">Engellenen saldırı, başarılı saldırı ve ekonomik kayıp</div></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th class="num">Güvenlik</th><th class="num">Engellenen</th><th class="num">Başarılı saldırı</th><th class="num">Kayıp</th><th class="num">Başarısız iş</th><th class="num">Zaman aşımı</th></tr></thead><tbody>${list.slice().sort((a,b)=>Number(b.guvenlikPuani)-Number(a.guvenlikPuani)).map(c=>`<tr><td class="name">${esc(c.sirketAdi)}</td><td class="num good">${n(c.guvenlikPuani)}</td><td class="num good">${i(c.engellenenSaldiriSayisi)}</td><td class="num ${Number(c.basariliSaldiriSayisi)>0?'bad':''}">${i(c.basariliSaldiriSayisi)}</td><td class="num bad">${m(c.toplamGuvenlikKaybi)}</td><td class="num">${i(c.basarisizIsSayisi)}</td><td class="num">${i(c.zamanAsiminaUgrayanIsSayisi)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="head"><div class="title">CANLI MOTOR AKIŞI</div></div><div id="log" class="log">${events.map(x=>`<div class="logline"><span>${esc(x.zaman||x.zamanDamgasi||'—')}</span><b>${esc(x.seviye||x.tur||'BİLGİ')}</b><span>${esc(x.mesaj||x.aciklama||JSON.stringify(x))}</span></div>`).join('')||'<div class="empty">Motor kaydı yok.</div>'}</div></section>`}
function render(data){S.data=data;const list=companies(data),overview=companySection(data,list),apps=appSection(data),protocols=protocolSection(data),services=serviceSection(data),finance=financeSection(data,list),operations=operationSection(data),security=securitySection(data,list);document.getElementById('home').innerHTML=[overview,apps,protocols,services,finance,operations,security].join('<div class="home-separator"></div>');document.getElementById('overview').innerHTML=overview;document.getElementById('apps').innerHTML=apps;document.getElementById('protocols').innerHTML=protocols;document.getElementById('services').innerHTML=services;document.getElementById('finance').innerHTML=finance;document.getElementById('operations').innerHTML=operations;document.getElementById('security').innerHTML=security;const log=document.querySelector('#security #log');if(log)log.scrollTop=log.scrollHeight}
function showView(view){const target=document.getElementById(view)||document.getElementById('home');S.activeView=target.id;document.querySelectorAll('.page').forEach(page=>{page.hidden=page!==target;page.setAttribute('aria-hidden',page===target?'false':'true')});document.querySelectorAll('.tab[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===target.id));history.replaceState(null,'',`#${target.id}`);window.scrollTo({top:0,behavior:'smooth'})}
document.querySelector('.tabs').addEventListener('click',event=>{const button=event.target.closest('.tab[data-view]');if(!button)return;event.preventDefault();showView(button.dataset.view)});
async function refresh(){if(S.loading)return;S.loading=true;const started=performance.now();try{const response=await fetch(`/api/durum?v=4.2&t=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();render(data);document.getElementById('dot').className='dot ok';document.getElementById('connection').textContent='CANLI';document.getElementById('motor').textContent=data.motor?.motorKimligi||'—';document.getElementById('tick').textContent=data.motor?.tickNumarasi??0;document.getElementById('latency').textContent=`${Math.round(performance.now()-started)} ms`}catch(error){document.getElementById('dot').className='dot bad';document.getElementById('connection').textContent='BAĞLANTI YOK';console.error(error)}finally{S.loading=false}}
setInterval(()=>document.getElementById('clock').textContent=new Date().toLocaleTimeString('tr-TR'),250);setInterval(refresh,500);const initial=location.hash.slice(1);showView(document.getElementById(initial)?.classList.contains('page')?initial:'home');refresh();
</script>
</body>
</html>
""";
}
